export function codeLabel(lang: Lang, code: string): string {
  const translated = CODE_LABELS[lang]?.[code] ?? CODE_LABELS.ko?.[code];
  if (translated) return translated;
  return code
    .replaceAll("_", " ")
    .toLowerCase()
    .replace(/^./, (letter) => letter.toUpperCase());
}

export function t(lang: Lang, key: string): string {
  const localized = dictionaries[lang]?.[key];
  if (localized?.trim()) return localized;
  const english = dictionaries.en[key];
  if (english?.trim()) return english;
  const korean = dictionaries.ko[key];
  return korean?.trim() ? korean : key;
}
